  <script>
    (function() {
      const form = document.getElementById('intakeForm');
      const successMsg = document.getElementById('successMessage');

      form.addEventListener('submit', async function(e) {
        e.preventDefault();

        const formData = new FormData(form);
        const payload = {};

        formData.forEach((value, key) => {
          payload[key] = value;
        });

        // Build a plain-text email body from the payload
        let body = '=== New Consulting Intake Submission ===\n\n';
        const fields = [
          ['company_name', 'Company Name'],
          ['website', 'Website'],
          ['contact_name', 'Contact Name'],
          ['contact_email', 'Email'],
          ['phone', 'Phone'],
          ['employee_count', 'Employees'],
          ['industry', 'Industry'],
          ['pain_points', 'Pain Points'],
          ['budget_range', 'Budget Range'],
          ['referral_source', 'Referral Source']
        ];

        fields.forEach(([key, label]) => {
          const val = payload[key] || '';
          body += label + ': ' + val + '\n';
        });

        // Use Formspree-style action — POST to agentmail endpoint
        // The form action already points there with hidden fields.
        // Since we need actual submit, we'll use fetch.
        const submitBtn = form.querySelector('.btn-submit');
        submitBtn.disabled = true;
        submitBtn.textContent = 'Submitting...';

        try {
          const resp = await fetch('https://agentmail.to/api/send', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({
              to: 'crowdedbutton536@agentmail.to',
              subject: 'New Consulting Intake: ' + (payload.company_name || 'Unknown Company'),
              content_type: 'text/plain',
              body: body
            })
          });

          if (!resp.ok) throw new Error('HTTP ' + resp.status);

          form.style.display = 'none';
          successMsg.style.display = 'block';

          // Also append to hidden iframe fallback
          const iframe = document.createElement('iframe');
          iframe.style.display = 'none';
          iframe.name = 'hidden-form-submit';
          document.body.appendChild(iframe);

          // Reset form but keep hidden
          form.target = 'hidden-form-submit';
          form.submit();
        } catch (err) {
          // Fallback: traditional form submit
          form.submit();
        }
      });
    })();
  </script>
